SELECT 
    ROUND(100.0 * SUM(CASE WHEN payment_type = 'Credit card' THEN 1 ELSE 0 END) / COUNT(*), 4) AS credit_card_percentage
FROM fct_trips;

SELECT 
    ROUND(100.0 * SUM(CASE WHEN is_weekend THEN 1 ELSE 0 END) / COUNT(*), 2) AS weekend_percentage
FROM fct_trips;

SELECT 
    (SUM(CASE WHEN pickup_date < '2023-07-01' THEN total_amount ELSE 0.0 END) / SUM(total_amount)) * 100 AS percentage_revenue_jan_to_jun
FROM fct_trips;

SELECT AVG(daily_trips) AS avg_trips_per_day
FROM (
  SELECT pickup_date, COUNT(*) AS daily_trips
  FROM fct_trips
  GROUP BY pickup_date
) t;

SELECT AVG(daily_revenue) AS avg_daily_revenue
FROM (
  SELECT pickup_date, SUM(total_amount) AS daily_revenue
  FROM fct_trips
  GROUP BY pickup_date
) t;

SELECT MEDIAN(trip_count) AS median_trips_per_day
FROM (
  SELECT pickup_date, COUNT(*) AS trip_count
  FROM fct_trips
  GROUP BY pickup_date
) t;

SELECT COUNT(*) AS trip_count
FROM fct_trips
WHERE fare_amount > (SELECT AVG(fare_amount) FROM fct_trips);

